[{"order":1,"type":"heading","text":"Field Validation, Clean Methods, and Formsets in Django"},{"order":2,"type":"paragraph","text":"Django forms provide a robust framework for validating user input, handling data sanitization, and managing multiple forms simultaneously using formsets. This tutorial explores advanced validation techniques using field-level validation, clean methods, and formsets."},{"order":3,"type":"subheading","text":"Field-Level Validation"},{"order":4,"type":"paragraph","text":"Field-level validation occurs during the cleaning of individual fields. By defining a method named clean_<fieldname> on your form class, Django automatically runs this method when is_valid() is called."},{"order":5,"type":"code","text":"from django import forms
from django.core.exceptions import ValidationError

class RegistrationForm(forms.Form):
    username = forms.CharField(max_length=50)
    email = forms.EmailField()

    def clean_username(self):
        data = self.cleaned_data['username']
        if 'admin' in data.lower():
            raise ValidationError('Username cannot contain the word admin.')
        return data"},{"order":6,"type":"subheading","text":"Cross-Field Validation Using clean()"},{"order":7,"type":"paragraph","text":"When your validation logic depends on multiple fields interacting together, you should override the clean() method of the form. At this stage, individual field cleaning has already completed, and clean_data contains all valid field values."},{"order":8,"type":"code","text":"class EventForm(forms.Form):
    start_date = forms.DateField()
    end_date = forms.DateField()

    def clean(self):
        cleaned_data = super().clean()
        start = cleaned_data.get('start_date')
        end = cleaned_data.get('end_date')

        if start and end and start > end:
            raise ValidationError('End date must occur after start date.')
        return cleaned_data"},{"order":9,"type":"subheading","text":"Introduction to Formsets"},{"order":10,"type":"paragraph","text":"Formsets are a layer of abstraction above working with multiple forms on a single page. They manage a sequence of form instances, making it easy to add, edit, or delete multiple records in a single submission."},{"order":11,"type":"code","text":"from django.forms import formset_factory

class ItemForm(forms.Form):
    name = forms.CharField(max_length=100)
    quantity = forms.IntegerField(min_value=1)

ItemFormSet = formset_factory(ItemForm, extra=3)"},{"order":12,"type":"subheading","text":"Validating Formsets"},{"order":13,"type":"paragraph","text":"Just like single forms, formsets have a clean() method and can raise validation errors that apply to the entire set of forms, such as ensuring unique entries across all rows."},{"order":14,"type":"code","text":"from django.forms import BaseFormSet

class BaseItemFormSet(BaseFormSet):
    def clean(self):
        if any(self.errors):
            return

        names = []
        for form in self.forms:
            if self.can_delete and self._should_delete_form(form):
                continue
            name = form.cleaned_data.get('name')
            if name in names:
                raise ValidationError('Item names must be unique.')
            names.append(name)

BoundedItemFormSet = formset_factory(ItemForm, formset=BaseItemFormSet, extra=2)"},{"order":15,"type":"bullet_point","text":"Always call super().clean() inside custom clean methods to preserve parent behavior."},{"order":16,"type":"bullet_point","text":"Raise ValidationError with descriptive messages to improve user experience."},{"order":17,"type":"bullet_point","text":"Use formsets when dealing with tabular data entry or dynamic lists of identical form structures."}]
